import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Admin trend source configuration","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-trend-source-config/spec.md","filePath":"feature/admin-trend-source-config/spec.md"}'),r={name:"feature/admin-trend-source-config/spec.md"};function o(s,e,c,d,l,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="admin-trend-source-configuration" tabindex="-1">Admin trend source configuration <a class="header-anchor" href="#admin-trend-source-configuration" aria-label="Permalink to &quot;Admin trend source configuration&quot;">​</a></h1><h2 id="objective-and-user-story" tabindex="-1">Objective and user story <a class="header-anchor" href="#objective-and-user-story" aria-label="Permalink to &quot;Objective and user story&quot;">​</a></h2><p>Admin can change the Facebook page/group list and maximum posts per source used by the bundled trend pipeline, without editing files or changing its downstream flow.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Manage pages and groups together, one public Facebook source URL per line.</li><li>Retain the current page/group list and FB_MAX_POSTS (default 50) until first save.</li><li>Accept 1–50 distinct sources and 1–1000 posts per source; these are technical bounds, not a promise that Facebook returns that many posts. Show the maximum possible run total (source count × posts per source).</li><li>Manual and scheduled runs use the same durable configuration. Freeze a snapshot for each new run; saving while running only affects later runs. Recovery retains the original saved files and never uses new sources or triggers a new crawl.</li><li>Admin-only read/update, internal-key protected AI routes, successful-update audit.</li><li>Reject malformed/non-Facebook/post URLs, duplicate identities, empty lists and stale revisions. Never fall back to crawling all defaults after invalid saved data.</li><li>Preserve cron, legacy ScrapeCreators/Apify configuration, worker stages and storage.</li></ul><h2 id="ui-ux-and-states" tabindex="-1">UI/UX and states <a class="header-anchor" href="#ui-ux-and-states" aria-label="Permalink to &quot;UI/UX and states&quot;">​</a></h2><p>Compact expandable configuration within Admin &gt; Trends &gt; Trend pipeline. Direct URL textarea, numeric limit and save/cancel. Saving does not run a pipeline. Keep unsaved input during status polling; show loading, error, stale-revision, pending and saved states. No native alerts. Keyboard labels and narrow-screen wrapping. All new strings use admin.trendSourceConfig.* in both vi/en admin.json files. Use existing semantic theme tokens and verify light/dark mode; no new palette.</p><h2 id="api-contract" tabindex="-1">API contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API contract&quot;">​</a></h2><p>GET /api/v1/admin/ai/trend-pipeline/source-config returns {revision, sourceUrls, maxPostsPerSource}; PATCH accepts the same object with the revision last read. Internal GET/POST use /api/v1/ai/trends/pipeline/source-config. 400 invalid settings, 409 stale revision, 503 unavailable configuration store. No cookies, credentials, filesystem paths or shell commands in requests/responses.</p><h2 id="definition-of-done-out-of-scope" tabindex="-1">Definition of done / out of scope <a class="header-anchor" href="#definition-of-done-out-of-scope" aria-label="Permalink to &quot;Definition of done / out of scope&quot;">​</a></h2><p>Verified shared snapshots, concurrent updates, admin guards and mocked UI flows. No live crawl/paid AI for QA. No DB migration/init/seeder changes, subscription, Facebook login UI, schedule editing, per-source heterogeneous limits or total-run cap.</p>',11)])])}const f=a(r,[["render",o]]);export{h as __pageData,f as default};
